const workflows = {
  plan: {count:'01 — MAÑANA', title:'Aterriza lo que importa.', text:'Convierte una semana abierta en un día posible. Arrastra tus prioridades y deja aire entre ellas.', list:['Elige hasta 5 prioridades','Protege bloques sin reuniones','Comparte el contexto, no el ruido'], label:'Plan de hoy', action:'Simular mi día'},
  focus: {count:'02 — BLOQUE DE FOCO', title:'Haz espacio para lo profundo.', text:'Activa un bloque y deja que el tablero proteja una sola intención a la vez.', list:['Un objetivo por bloque','Silencia el contexto secundario','Cierra el ciclo con una nota'], label:'Modo enfoque · 42:18', action:'Iniciar bloque'},
  reflect: {count:'03 — FINAL DEL DÍA', title:'Cierra con una idea clara.', text:'Recupera lo que avanzó, lo que aprendiste y la primera acción de mañana.', list:['Celebra el progreso real','Captura lo que cambió','Deja una pista para mañana'], label:'Cierre de jornada', action:'Guardar reflexión'}
};
const tabs = document.querySelectorAll('.workflow-tab');
const setWorkflow = key => { const item=workflows[key]; document.getElementById('stepCount').textContent=item.count; document.getElementById('workflowTitle').textContent=item.title; document.getElementById('workflowText').textContent=item.text; document.getElementById('uiLabel').textContent=item.label; document.getElementById('demoAction').innerHTML=`${item.action} <span>→</span>`; document.getElementById('workflowList').innerHTML=item.list.map(x=>`<li>${x}</li>`).join(''); tabs.forEach(t=>t.classList.toggle('active',t.dataset.workflow===key)); };
tabs.forEach(tab=>tab.addEventListener('click',()=>setWorkflow(tab.dataset.workflow)));
document.getElementById('demoAction').addEventListener('click',e=>{e.currentTarget.classList.toggle('done');e.currentTarget.innerHTML=e.currentTarget.classList.contains('done')?'Listo por ahora ✓':'Simular mi día <span>→</span>';});
document.getElementById('weekToggle').addEventListener('click',e=>{const alt=e.currentTarget.getAttribute('aria-pressed')==='false';e.currentTarget.setAttribute('aria-pressed',alt);e.currentTarget.textContent=alt?'Volver a resumen':'Ver otra vista';document.getElementById('focusHours').textContent=alt?'4':'12h 40m';document.getElementById('completionRate').textContent=alt?'5':'78%';document.getElementById('metricInsight').textContent=alt?'Cinco bloques protegidos esta semana. Cada uno cuenta como una decisión de cuidar tu atención.':'Tu mejor ventana fue el martes por la mañana. Intenta protegerla de nuevo.';});
document.getElementById('waitlistButton').addEventListener('click',()=>document.getElementById('waitlistForm').hidden=false);
document.getElementById('waitlistForm').addEventListener('submit',e=>{e.preventDefault();document.getElementById('formMessage').textContent='Gracias. Esta demo no envía datos: es una interacción de muestra.';});

